// A small house: walls are lines/polylines with height -> become 3D walls
cad.layer('Walls', '#e0e0e0');
cad.defaults({ height: 3, width: 3 });
cad.polygon([[0,0],[12,0],[12,9],[0,9]]);          // outer walls
cad.line(6, 0, 6, 5.5);                            // inner wall
cad.line(6, 5.5, 12, 5.5);
cad.layer('Doors', '#ffb74d');
cad.defaults({ height: 0, width: 1.5 });
cad.arc(6, 5.5, 1, 90, 180);
cad.arc(1, 0, 1, 0, 90);
cad.layer('Furniture', '#4fc3f7');
cad.rect(0.5, 0.5, 2, 1, { height: 0.75, fill: '#4fc3f7' });   // desk
cad.circle(9, 2.5, 0.8, { height: 0.7, fill: '#4fc3f7' });      // table
cad.layer('Labels', '#9aa2b1');
cad.text(1, 7, 'Living room', { size: 0.6 });
cad.text(7, 7, 'Bedroom', { size: 0.6 });
cad.text(7, 1, 'Kitchen', { size: 0.6 });
cad.dim(0, -1, 12, -1);
cad.dim(-1, 0, -1, 9);
cad.zoomExtents();
